{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, the highest-transfer analogue (0.9056), has an absolute oral bioavailability of 34% in humans; the query shares the dimethoxyphenyl and basic amine scaffold, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a close structural analogue with a dimethoxy-tetrahydroisoquinoline core, has an absolute oral bioavailability of approximately 49% in humans, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, another dimethoxy-substituted isoquinoline analogue, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a dimethoxyphenyl basic amine analogue, has an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, a basic amine analogue with limited passive permeability, still achieves 23.4% absolute oral bioavailability, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "One verapamil study reported 19.4% bioavailability, just below the 20% threshold, indicating some uncertainty; however, most verapamil and other analogue values are ≥ 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of high-transfer experimental evidence from verapamil, valbenazine, noscapine, encainide, and levosulpiride indicates absolute oral bioavailability ≥ 20%. The query's structural similarity to these compounds, especially verapamil and valbenazine, supports a high prediction despite a few borderline verapamil values.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "Verapamil data straddle the 20% threshold (18–20%, 19.4%), creating some uncertainty.",
    "Exact metabolic stability and transporter effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

